CREATE PROCEDURE [LogTransazioniTotem_selectrow]
	@P_1 BigInt,
	@sync_scope_local_id Int,
	@sync_scope_restore_count Int
AS
BEGIN
SELECT [side].[id], [base].[IdCli], [base].[data], [base].[idpost], [base].[MName], [base].[tipo], [base].[valore], [base].[IDTerm], [base].[CAut], [base].[TCC], [base].[Stan], [base].[AId], [base].[Appl], [base].[Cryptogram], [base].[AC], [base].[IAD], [base].[IC], [base].[PAN], [base].[DataOraChiusura], [base].[IdOperatore], [side].[sync_row_is_tombstone], [side].[local_update_peer_timestamp] as sync_row_timestamp, case when ([side].[update_scope_local_id] is null or [side].[update_scope_local_id] <> @sync_scope_local_id) then COALESCE([side].[restore_timestamp], [side].[local_update_peer_timestamp]) else [side].[scope_update_peer_timestamp] end as sync_update_peer_timestamp, case when ([side].[update_scope_local_id] is null or [side].[update_scope_local_id] <> @sync_scope_local_id) then case when ([side].[local_update_peer_key] > @sync_scope_restore_count) then @sync_scope_restore_count else [side].[local_update_peer_key] end else [side].[scope_update_peer_key] end as sync_update_peer_key, case when ([side].[create_scope_local_id] is null or [side].[create_scope_local_id] <> @sync_scope_local_id) then [side].[local_create_peer_timestamp] else [side].[scope_create_peer_timestamp] end as sync_create_peer_timestamp, case when ([side].[create_scope_local_id] is null or [side].[create_scope_local_id] <> @sync_scope_local_id) then case when ([side].[local_create_peer_key] > @sync_scope_restore_count) then @sync_scope_restore_count else [side].[local_create_peer_key] end else [side].[scope_create_peer_key] end as sync_create_peer_key from [LogTransazioniTotem] [base] right join [LogTransazioniTotem_tracking] [side] on [base].[id] = [side].[id] WHERE [side].[id] = @P_1
END
